void MainWindow::setupMenuBar() {
    auto* file_menu = menuBar()->addMenu(QStringLiteral("&File"));
    file_menu->addAction(QStringLiteral("&Connect..."), this, [this]() {
        auto dialog = muscovite::qt::ui::ConnectionProfileDialog{this};
        if (dialog.exec() != QDialog::Accepted) return;
        auto& auth_manager = muscovite::qt::AuthManager::instance();
        auto config = auth_manager.config();
        config.serverAddress = dialog.endpoint();
        auth_manager.configure(config);
        setConnectionStatus(QStringLiteral("Endpoint: %1").arg(dialog.endpoint()));
    });
    file_menu->addAction(QStringLiteral("&Quit"), QApplication::instance(),
                         &QApplication::quit, QKeySequence::Quit);

    auto* edit_menu = menuBar()->addMenu(QStringLiteral("&Edit"));
    edit_menu->addAction(QStringLiteral("&Refresh"), this, [this]() {
        if (auto* current = qobject_cast<QWidget*>(tab_widget_->currentWidget()); current != nullptr) {
            QMetaObject::invokeMethod(current, "refreshRequested", Qt::QueuedConnection);
        }
    }, QKeySequence::Refresh);

    auto* view_menu = menuBar()->addMenu(QStringLiteral("&View"));
    view_menu->addAction(QStringLiteral("Toggle &Navigation"), this, [this]() {
        nav_dock_->setVisible(!nav_dock_->isVisible());
    });
#ifdef MUSCOVITE_OBSERVABILITY_PANEL
    view_menu->addAction(QStringLiteral("📊 &Observability"), this, [this]() {
        if (obs_dock_) obs_dock_->setVisible(!obs_dock_->isVisible());
    });
#endif // MUSCOVITE_OBSERVABILITY_PANEL
}

